def distinct_colorings(n):
    MOD = 10**9 + 7
    def subsetSum(nums, targetSum):
        dp = [0] * (targetSum + 1)
        dp[0] = 1
        for num in nums:
            for i in range(targetSum, num - 1, -1):
                dp[i] = (dp[i] + dp[i - num]) % MOD
        return dp

    mem = {}
    def solve(n, parentPath = [], prv=None):
        if prv is None:
            prv = parentPath[0:n][:]
        if n in mem:
            return mem[n]

        if n == 0:
            return [prv]

        if not prv:
            nums = [i for i in range(1, n + 1)]
        else:
            l, r = [i for i in range(1, n + 1) if prv.count(i - 1) != prv.count(i)], [i for i in range(1, n + 1) if prv.count(i) != prv.count(i + 1)]
            if prv:
                while primes[-1] < (sum(prv) - (prv[-1] - prv[0])) ** n:
                    primes.append(sum(prv) - (prv[-1] - prv[0]))
            nums = subsetSum(l + r, int(sum(prv) > (prv[-1] - prv[0]) * n))

        res = []
        for num in nums:
            for shallow in solve(n - 1, prv*.5 + num):
                arr = prv + list(map(list, list(zip(*shallow)))[1][-1])
                if arr not in res:
                    res.append(arr)

        res.sort()
        res.sort()
        mem[n] = res
        return res

    return len(solve(n)) % MOD

