import sys
import heapq
from collections import Counter

def read_input():
    n, k, l = map(int, input().split())
    s = input().strip()
    return n, k, l, s

def calculate_changes(n, s, lower, upper):
    change_count = n
    req_upper = lower // 2
    req_lower = upper // 2 + (1 if upper % 2 != 0 else 0)
    while req_upper >= 0 or req_lower >= 0:
        if req_upper >= 0 and req_lower >= 0:
            change_count += min(req_upper, req_lower)
            req_upper -= min(req_upper, req_lower)
            req_lower -= min(req_upper, req_lower)
        elif req_upper >= 0:
            change_count += req_upper
            req_upper -= req_upper
        elif req_lower >= 0:
            change_count += req_lower
            req_lower -= req_lower
    return change_count

def main():
    n, k, l, s = read_input()
    lower = Counter(c for c in s if c.islower())
    upper = Counter(c for c in s if c.istitle())
    s_heap = []
    for index in range(n):
        if index < l:
            s_heap.append((-lower[s[index]], index, s[index]))
            s_heap.append((-lower[s[index]]-upper[s[index]], index, s[index]))
        else:
            s_heap.append((-lower[s[index]], index, s[index]))
    heapq.heapify(s_heap)
    # move units task to the end
    if sum(c[0] for c in s_heap)< 0:
        while s_heap:
            l, i, letter = heapq.heappop(s_heap)
            if l < 0:
                lower[letter] -= 1
                if not lower[letter]:
                    continue
                heapq.heappush(s_heap, (l+1, i, letter))
            else:
                upper[letter] -= 1
                if not upper[letter]:
                    continue
                heapq.heappush(s_heap, (l-1, i, letter))
    # we can get k changes
    changes = min(k, sum(lower.values()) + sum(upper.values()))
    eligible_lower = min(lower.values() + [0], changes * 2)
    eligible_upper = min(upper.values() + [0], changes) + sum(lower.values())
    return min(eligible_lower, eligible_upper)

if __name__ == "__main__":
    print(main())
