        return None
    player = 1  # 1 for Alice, -1 for Bob
    for i in range(1, n-1, 2):
        if isAliceWinner(s[:i]):
            return 'Alice'
        if isAliceWinner(s[i+1:]):
            return 'Bob'
    return 'None' if n % 4 == 3 else 'Alice'

