def minimize_case_changes(n, k, l, handle):
    upper = 0
    lower = 0
    deleted = 0
    for char in handle:
        if char.isupper():
            upper += 1
        elif char.islower():
            lower += 1
        else:
            deleted += 1

    # Early return if we can't perform any changes
    if deleted >= n:
        return 0

    changes_possible = n - deleted - l
    if changes_possible < 0:
        return min(k, deleted % 2)
    else:
        return min(k, changes_possible // 2)

# Example usage
