def read_ints():
    return list(map(int, sys.stdin.readline().split()))

def process():
    n, m = read_ints()
    strings = []
    for i in range(m):
        si, fi = read_ints()
        temp = []
        for j in range(1 << fi):
            temp.append(1 - si)
        strings.append(temp)

    total_count = defaultdict(list)
    for i in range(m):
        for j in range(n):
            total_count[i^strings[i][j]].append(j)

    max_triplets = 0
    for triple_count in total_count.values():
        triple_count.sort()
        if (len(triple_count) >= 3):
            max_triplets += len(triple_count) * (len(triple_count) - 1) // 2

    return max_triplets

