def dfs(n, skills):
    dp = defaultdict(int)
    dp[n] = 1

    for s in skills:
        new_dp = defaultdict(int)
        for i in range(1, s+1):
            for j in range(n):
                if dp[j] > 0:
                    new_dp[j] += dp[j]
                    if j + i < n:
                        new_dp[j + i] += dp[j]
                    if j - i >= 0:
                        new_dp[j - i] += dp[j]
        dp, temp = new_dp, new_dp
        for i in range(n):
            if temp[i] > 0:
                dp[i] = temp[i]

    return sum(temp.values()) % (10**9 + 7)

