MOD = 10**9 + 7

def solve(skill):
    sm = sum(skill)
    sds = [[0]*sm for _ in range(sm)]
    vals = sorted(set(skill))

    for i in range(sm+1):
        sds[0][i] = (1, 1)

    sumskill = [0]
    for i, val in enumerate(skill, 1):
        sumskill.append(sumskill[-1] + val)
        for c in vals:
            for sc in range(c+1, 1, -1):
                for i0, li in enumerate(sds[i-1]):
                    if li[0] > 0 and sds[i-1][li[0]] <= sc and sds[i-1][li[1]-sc][0] >= i0:
                        sds[i][i-1 if c == vals[-1] else li[0]] = (sds[i][i-1 if c == vals[-1] else li[0]][0] + sds[i-1][li[0]] - li[1], min(li[1] - 2 * min(li[0], li[1]), 0))
                    sds[i][i-1 if c == vals[-1] else li[0] if li[0] <= c else sumskill[-1] - 1] = (sds[i][i-1 if c == vals[-1] else li[0] if li[0] <= c else sumskill[-1] - 1][0] + sds[i-1][li[0]] - i + 1, max(0, sds[i-1][li[0]] - i))

    sum_skill, backtrack = 0, {}
    for c in vals:
        for i0, li in enumerate(sds[sm][c:], 1):
            if backtrack[i0-1, sum_skill - li[0]] < 0:
                backtrack[i0-1, sum_skill - li[0]] = i0
            sum_skill += li[0]

    def dfs(x, y, rng, ex):
        if rng >= sm:
            return 1

        res, maxex = 0, rng // 2
        for x0, sds in backtrack.items():
            if sds > rng or not ex or x0 > rng or (x0 <= rng and x0 + maxex > x):
                continue
            res = (res + li) % MOD

        if maxex or x <= rng or (ex and x - maxex > rng):
            return res

        left, right, pow2, pow2k2 = y, rng, 1, 1
        while left - 1 < right:
            mid = (left + right + 1) // 2
            res = (res + li * dfs(x, left - (y + 1), left - y + 1 - mid, right - mid > 0)) % MOD

        return res

    return dfs(sm-1, sm-1, sm // 2, e := skill.count(1))

