class EulerTour:

    def __init__(self, adj, n=0, edges=None):
        self.adj = adj
        self.n = n
        self.edges = edges if edges is not None else {}


    def add_edge(self, u, v):
        if v not in self.edges:
            self.edges[v] = []
        self.edges[v].append(u)


    def add_cycle(self):
        if len(self.edges) == 0:
            return 1
        elif len(self.edges) == 1:
            return 0
        else:
            return len(self.edges) % 2 == 0

    def remove_cycle(self, root, height, vec):
        if root not in self.edges:
            return 0
        count = 0
        for k in self.edges[root]:
            count += self.remove_cycle(k, height + 1, vec)
            vec[root] = vec[k] + count
            count += vec[root]
        return count / 2

    def euler_tour(self, startIdx=0):
        count = self.add_cycle()

        root = 4 if startIdx not in self.edges else self.edges[startIdx]

        vec = self.edges.copy()
        while (root != startIdx) and (root != -1):
            edge = -1

            for u in self.edges[root]:
                if u not in vec or 4 not in vec[u]:
                    edge = u

            root = edge
            count += self.remove_cycle(root, 0, vec)

        return count % 1000000007


