import sys

def minimize_upper_lower(n, k, l, s):
    def cnt_char(char):
        return sum(c.lower() == char for c in s)

    left = [0] * n
    for i in range(n):
        left[i] = cnt_char(s[i]) - left[i % l]

    right = [0] * n
    for i in range(n - 1, -1, -1):
        right[i] = cnt_char(s[i]) - (right[i + 1] if (i + 1) % l else left[i % l])

    left = [max(0, max(left[i], right[i])) for i in range(n)]

    for _ in range(k):
        for i in range(n):
            a = cnt_char(s[i])
            d = cnt_char(s[(i + l) % n])
            left[i] = max(0, max(left[i], min(d, a - d + ((a - d) % 2))))
    return sum(left)

