        strings.append(_filter_bits(prefix, suffix))
    print(find_max_sum_triples(strings))

# Helper function to filter bits
def _filter_bits(prefix, suffix):
    return "".join(("%s" % bit
                    if (("1" in str(prefix)) and ("1" in str(suffix))) # ascending order
                    else ("0" if bit == "1" else "1")
                    for bit in range(10))[0:11])

if __name__ == "__main__":
    main()
