def concise_notation(n):
    # Divide by 2 and add '2^' at first
    while n % 2 == 0:
        n //= 2
        result += '2^'

    # Divide by 5 and add '5^' when after division we just divide by 1
    if n % 5 == 0:
        n //= 5
        while n % 2 == 0:
            result += '2^5'
            n //= 5

    # Divide by 3 and add '3^' under '2^5'
    if n % 3 == 0:
        n //= 3
        while n % 2 == 0 and n % 3 == 0:
            result += '2^53'
            n //= 3

    # Remaining n which is divisible by 1 is just add '1^' under '2^5'
    while n % 2 == 0 or n % 5 == 0 or n % 3 == 0:
        if n % 2 == 0:
            n //= 2
            if n % 5 != 0 and n % 3 != 0:
                result += '2^5'
        if n % 5 == 0:
            n //= 5
            if n % 3 != 0 and n % 2 != 0:
                result += '2^53'
        if n % 3 == 0:
            n //= 3
            result += '2^53'

    # The result starts with 2 so remove '2^' at the beginning (If it exists)
    if result.startswith('2^'):
        result = result.replace('2^', '', 1)

    return result

# Example usage
n = 1234567890
print(concise_notation(n))  # Output will be a concise notation based on the constraints
