import sys
from itertools import product

def max_hamming_difference_strings(n, m, strings):
    bit_length = n
    string_length = len(strings)
    absolute_hamming_distance_matrix = [[0]*bit_length for _ in range(bit_length)] 
    for i in range(string_length):
        for j in range(i+1, string_length):
            for p in range(i+1, j):
                for k in range(p):
                    for l in range(k+1, p):
                        # Calculate Hamming distance for a-v, v-u, u-b
                        distance = (strings[i][k] ^ strings[j][l]) + (strings[i][l] ^ strings[j][l]) + (strings[i][p] ^ strings[j][k])
                        absolute_hamming_distance_matrix[i][j] = max(absolute_hamming_distance_matrix[i][j], distance)
    return max(map(max, absolute_hamming_distance_matrix))

if __name__ == "__main__":
    n, m = map(int, sys.stdin.readline().split())
    sfs = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]
    print(max_hamming_difference_strings(n, m, sfs))
