def simplify_number(n):
    if n < 100:
        return str(n)
    elif n < 10000:
        return '10' + '0' * (len(str(n)) - 2)
    else:
        exp = 8  # log10(1000000000)
        num = round(n / 100000000000)  # 10^9 + x, need one more exp
        return str(num) + '^' + str(exp)

print(simplify_number(2018))
print(simplify_number(1000000007))
print(simplify_number(10000000000))
print(simplify_number(2000000000))
